examples.source:
workspace {
  model {
    u = person "User" "Buys things"
    s = softwareSystem "Shop" "Sells goods"
    pay = softwareSystem "Payments" "3rd party" "Ext"
    u -> s "Orders" "HTTPS"
    s -> pay "Charges"
  }
  views {
    systemContext s {
      include *
      autolayout lr
    }
    styles {
      element "Ext" {
        background #999999
      }
      element "Person" {
        shape person
      }
    }
  }
}

workspace {
  model {
    u = person "User"
    s = softwareSystem "Shop" {
      web = container "Web" "UI" "React"
      api = container "API" "Logic" "Go"
      db = container "DB" "Orders" "Postgres" "Database"
    }
    u -> web "Uses"
    web -> api "Calls" "JSON"
    api -> db "Reads" "SQL"
  }
  views {
    container s {
      include *
      autolayout tb
    }
    styles {
      element "Database" {
        shape cylinder
        background #ffcc00
      }
      relationship "Relationship" {
        dashed true
      }
    }
  }
}

workspace {
  model {
    s = softwareSystem "Shop" {
      api = container "API" {
        ctl = component "Controller"
        svc = component "Service"
      }
    }
    ctl -> svc "Calls"
  }
  views {
    component api {
      include *
      autolayout
    }
  }
}

workspace {
  model {
    s = softwareSystem "Shop" {
      web = container "Web"
      db = container "DB"
    }
    web -> db "Reads"
    live = deploymentEnvironment "Live" {
      n = deploymentNode "Server" {
        containerInstance web
        containerInstance db
      }
    }
  }
  views {
    deployment s "Live" {
      include *
      autolayout
    }
  }
}

workspace {
  model {
    u = person "User"
    s = softwareSystem "Shop" {
      web = container "Web"
      db = container "DB"
    }
    u -> web "Uses"
    web -> db "Reads"
  }
  views {
    dynamic s {
      u -> web "Opens page"
      web -> db "Queries"
      autolayout
    }
  }
}

workspace "Org" "Landscape" {
  model {
    group "Internal" {
      a = softwareSystem "CRM"
      b = softwareSystem "ERP"
    }
    u = person "Staff"
    u -> a "Uses"
    a -> b "Syncs"
  }
  views {
    systemLandscape {
      include *
      title "Landscape"
    }
  }
}
